BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(21);
SELECT ok(to_regprocedure('app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)') IS NOT NULL, 'P37 private Section candidate source installed');
SELECT is((SELECT proowner::regrole::text FROM pg_proc WHERE oid='app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)'::regprocedure),'schoolos_schema_owner'::text,'only schema owner owns P37');
SELECT ok(NOT (SELECT prosecdef FROM pg_proc WHERE oid='app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)'::regprocedure),'P37 uses invoker security, not privilege elevation');
SELECT ok((SELECT EXISTS(SELECT 1 FROM unnest(proconfig) AS c(setting) WHERE regexp_replace(c.setting,'[[:space:]]','','g')='search_path=pg_catalog,pg_temp') FROM pg_proc WHERE oid='app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)'::regprocedure),'P37 fixes safe SQL search path');
SELECT ok(NOT EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid='app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)'::regprocedure AND acl.grantee=0 AND acl.privilege_type='EXECUTE'),'P37 denies PUBLIC function execute');
SELECT ok(NOT has_function_privilege('anon','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'anon cannot call protected candidate source');
SELECT ok(NOT has_function_privilege('authenticated','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'authenticated cannot call protected candidate source');
SELECT ok(NOT has_function_privilege('service_role','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'service_role cannot call protected candidate source');
SELECT ok(NOT has_function_privilege('schoolos_workflow_executor','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'schoolos_workflow_executor cannot call protected candidate source');
SELECT ok(NOT has_function_privilege('schoolos_file_login','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'schoolos_file_login cannot call protected candidate source');
SELECT ok(NOT has_function_privilege('schoolos_platform_executor','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'schoolos_platform_executor cannot call protected candidate source');
SELECT ok(NOT has_function_privilege('schoolos_identity_executor','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'schoolos_identity_executor cannot call protected candidate source');
SELECT ok(NOT has_function_privilege('schoolos_evidence_writer','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'schoolos_evidence_writer cannot call protected candidate source');
SELECT ok(NOT has_function_privilege('schoolos_authz_reader','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'schoolos_authz_reader cannot call protected candidate source');
SELECT ok(NOT has_function_privilege('schoolos_student_executor','app_private.db03_principal_section_candidate_source(uuid,bigint,uuid,uuid)','EXECUTE'),'schoolos_student_executor cannot call protected candidate source');
SELECT throws_ok($q$SELECT app_private.db03_principal_section_candidate_source('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','cccccccc-cccc-4ccc-8ccc-cccccccccccc')$q$,'P0001','DB03 Principal Section candidate invalid','invalid expected version rejected');
SELECT throws_ok($q$SELECT app_private.db03_principal_section_candidate_source('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,NULL,'cccccccc-cccc-4ccc-8ccc-cccccccccccc')$q$,'P0001','DB03 Principal Section candidate invalid','missing real Forward rejected');
SELECT throws_ok($q$SELECT app_private.db03_principal_section_candidate_source('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',NULL)$q$,'P0001','DB03 Principal Section candidate invalid','missing Section id rejected');
SELECT is(app_private.db03_principal_section_candidate_source(NULL,1,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','cccccccc-cccc-4ccc-8ccc-cccccccccccc')::text,NULL::text,'missing application returns no candidate');
SELECT is(app_private.db03_principal_section_candidate_source('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','cccccccc-cccc-4ccc-8ccc-cccccccccccc')::text,NULL::text,'unknown application returns no candidate');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'P37 does not create an APPROVE command');
SELECT * FROM finish();
ROLLBACK;
